// #Sireum

package eit_acquisition_supervisor.EIT_Acquisition_Supervisor

import org.sireum._
import art.Art
import eit_acquisition_supervisor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait SupervisoryArbitration_acquisition_process_supervisory_arbitration_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_supervisory_arbitration)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_supervisory_arbitration)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_supervisory_arbitration)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_supervisory_arbitration)
  }

  /** helper function to set the values of all input ports.
   * @param recovery_frame payload for data port recovery_frame
   * @param session_frame payload for data port session_frame
   * @param cycle_frame payload for data port cycle_frame
   * @param image_frame payload for data port image_frame
   * @param collection_proposal payload for data port collection_proposal
   * @param release_proposal payload for data port release_proposal
   */
  def put_concrete_inputs(recovery_frame : EIT_Acquisition_Supervisor.RecoveryFrame,
                          session_frame : EIT_Acquisition_Supervisor.SessionFrame,
                          cycle_frame : EIT_Acquisition_Supervisor.CycleFrame,
                          image_frame : EIT_Acquisition_Supervisor.ImageFrame,
                          collection_proposal : EIT_Acquisition_Supervisor.Proposal.Type,
                          release_proposal : EIT_Acquisition_Supervisor.Proposal.Type): Unit = {
    put_recovery_frame(recovery_frame)
    put_session_frame(session_frame)
    put_cycle_frame(cycle_frame)
    put_image_frame(image_frame)
    put_collection_proposal(collection_proposal)
    put_release_proposal(release_proposal)
  }


  /** helper function to check SupervisoryArbitration_acquisition_process_supervisory_arbitration's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param decision_frame method that will be called with the value of the outgoing data
   *        port 'decision_frame'.
   */
  def check_concrete_output(decision_frame: EIT_Acquisition_Supervisor.DecisionFrame => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val decision_frameValue: EIT_Acquisition_Supervisor.DecisionFrame = get_decision_frame().get
    if(!decision_frame(decision_frameValue)) {
      testFailures = testFailures :+ st"'decision_frame' did not match expected: value of the outgoing data port is ${decision_frameValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_recovery_frame(value : EIT_Acquisition_Supervisor.RecoveryFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_supervisory_arbitration.operational_api.recovery_frame_Id, EIT_Acquisition_Supervisor.RecoveryFrame_Payload(value))
  }

  // setter for in DataPort
  def put_session_frame(value : EIT_Acquisition_Supervisor.SessionFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_supervisory_arbitration.operational_api.session_frame_Id, EIT_Acquisition_Supervisor.SessionFrame_Payload(value))
  }

  // setter for in DataPort
  def put_cycle_frame(value : EIT_Acquisition_Supervisor.CycleFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_supervisory_arbitration.operational_api.cycle_frame_Id, EIT_Acquisition_Supervisor.CycleFrame_Payload(value))
  }

  // setter for in DataPort
  def put_image_frame(value : EIT_Acquisition_Supervisor.ImageFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_supervisory_arbitration.operational_api.image_frame_Id, EIT_Acquisition_Supervisor.ImageFrame_Payload(value))
  }

  // setter for in DataPort
  def put_collection_proposal(value : EIT_Acquisition_Supervisor.Proposal.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_supervisory_arbitration.operational_api.collection_proposal_Id, EIT_Acquisition_Supervisor.Proposal_Payload(value))
  }

  // setter for in DataPort
  def put_release_proposal(value : EIT_Acquisition_Supervisor.Proposal.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_supervisory_arbitration.operational_api.release_proposal_Id, EIT_Acquisition_Supervisor.Proposal_Payload(value))
  }

  // getter for out DataPort
  def get_decision_frame(): Option[EIT_Acquisition_Supervisor.DecisionFrame] = {
    val value: Option[EIT_Acquisition_Supervisor.DecisionFrame] = get_decision_frame_payload() match {
      case Some(EIT_Acquisition_Supervisor.DecisionFrame_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port decision_frame.  Expecting 'EIT_Acquisition_Supervisor.DecisionFrame_Payload' but received ${v}")
      case _ => None[EIT_Acquisition_Supervisor.DecisionFrame]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_decision_frame_payload(): Option[EIT_Acquisition_Supervisor.DecisionFrame_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_supervisory_arbitration.initialization_api.decision_frame_Id).asInstanceOf[Option[EIT_Acquisition_Supervisor.DecisionFrame_Payload]]
  }

}
